20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "formatDisplayName")
27	    @Mapping(target = "initials", source = "owner", qualifiedByName = "formatInitials")
28	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "formatMembershipNumber")
29	    @Mapping(target = "membershipTier", source = "owner", qualifiedByName = "formatMembershipTier")
30	    @Mapping(target = "locality", source = "owner", qualifiedByName = "formatLocality")
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    /**
34	     * Formats an owner's name as {@code 'LastName, FirstName'} from the stored first and
35	     * last names, as required by the API's read-only {@code displayName} field.
36	     *
37	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
38	     * applied only where referenced via {@code qualifiedByName}.
39	     */
40	    @Named("formatDisplayName")
41	    default String formatDisplayName(Owner owner) {
42	        if (owner == null) {
43	            return null;
44	        }
45	        return owner.getLastName() + ", " + owner.getFirstName();
46	    }
47	
48	    /**
49	     * Formats an owner's initials as the upper-cased first letters of the first and last
50	     * names, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), as required by the
51	     * API's read-only {@code initials} field.
52	     *
53	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
54	     * applied only where referenced via {@code qualifiedByName}.
