250	        if (owner.isNew()) {
251	            LocalDate effectiveDate = owner.getRegistrationDate() != null
252	                ? owner.getRegistrationDate()
253	                : LocalDate.now();
254	            owner.setRegistrationDate(toBusinessDay(effectiveDate));
255	            if (owner.getCustomerCode() == null) {
256	                owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
257	            }
258	            if (owner.getNamesakeCount() == null) {
259	                owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
260	            }
261	        }
262	        ownerRepository.save(owner);
263	
264	    }
