266	    /**
267	     * Count the existing owners (before this create) that share the given first and last name,
268	     * compared case-insensitively, as required by the read-only {@code namesakeCount} field.
269	     */
270	    private int countNamesakes(String firstName, String lastName) {
271	        if (firstName == null || lastName == null) {
272	            return 0;
273	        }
274	        return (int) ownerRepository.findAll().stream()
275	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
276	                && lastName.equalsIgnoreCase(owner.getLastName()))
277	            .count();
278	    }
279	
280	    /**
281	     * Build a customer code formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3}
282	     * is the upper-cased first three letters of the owner's city, {@code LAST3} the
283	     * upper-cased first three letters of the owner's last name and {@code NNNN} a per-city,
284	     * 4-digit zero-padded sequence equal to one more than the current number of owners
285	     * already in that city (e.g. {@code 'LON-SMI-0007'}).
286	     */
287	    private String generateCustomerCode(String city, String lastName) {
288	        String cityName = city == null ? "" : city;
289	        String city3 = cityName.substring(0, Math.min(3, cityName.length())).toUpperCase();
290	        String name = lastName == null ? "" : lastName;
291	        String last3 = name.substring(0, Math.min(3, name.length())).toUpperCase();
292	        long sequence = countOwnersInCity(cityName) + 1L;
293	        return String.format("%s-%s-%04d", city3, last3, sequence);
294	    }
295	
296	    /**
297	     * Count the existing owners whose city matches the given city, compared case-insensitively,
298	     * used to derive the per-city sequence of the customer code.
299	     */
300	    private long countOwnersInCity(String city) {
301	        if (city == null) {
302	            return 0L;
303	        }
304	        return ownerRepository.findAll().stream()
305	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
306	            .count();
307	    }
